type User {
  email: String,
  name: String,
  password_hash: String,
  id: String,
}

type Signup {
  email: String,
  name: String,
  password: String,
}

type Profile {
  email: String,
  name: String,
}

type DisplayNameUpdate {
  name: String,
}

type UserError =
  | Taken(email: String)
  | BadLogin
  | NoSuchUser(email: String)

api fn signup(input: Signup) -> Result[Profile, UserError]
  route: POST "/users"
  effects: rand, store(users)
  requires: is_email(input.email) && str_len(trim(input.name)) > 0 && str_len(input.password) >= 8
{
  if is_some(get(users, input.email)) {
    return Err(Taken(input.email))
  }
  let user = User {
    email: input.email,
    name: trim(input.name),
    password_hash: hash_password(input.password),
    id: uuid(),
  }
  insert(users, user)
  return Ok(profile(user))
}

fn profile(u: User) -> Profile {
  return Profile { email: u.email, name: u.name }
}

api fn change_display_name(email: String, input: DisplayNameUpdate) -> Result[Profile, UserError]
  route: PATCH "/users/{email}"
  effects: store(users)
  requires: str_len(trim(input.name)) > 0 && str_len(trim(input.name)) <= 40
{
  match get(users, email) {
    Some(u) => rename_user(u, trim(input.name)),
    None => Err(NoSuchUser(email)),
  }
}

fn rename_user(user: User, name: String) -> Result[Profile, UserError]
  effects: store(users)
{
  var updated = user
  updated.name = name
  return Ok(profile(save(users, updated)))
}

api fn login(input: Signup) -> Result[Profile, UserError]
  route: POST "/login"
  effects: store(users)
{
  return match get(users, input.email) {
    Some(u) => match verify_password(input.password, u.password_hash) {
      true => Ok(profile(u)),
      false => Err(BadLogin),
    },
    None => Err(BadLogin),
  }
}

test "display name change is trimmed and persists through login" {
  let account = Signup { email: "ada@example.com", name: "Ada", password: "long-password" }
  assert(signup(account) == Ok(Profile { email: account.email, name: "Ada" }))
  let updated = Profile { email: account.email, name: "Ada Lovelace" }
  assert(change_display_name(account.email, DisplayNameUpdate { name: "  Ada Lovelace  " }) == Ok(updated))
  assert(login(account) == Ok(updated))
}

test "display name change for a missing user" {
  let email = "missing@example.com"
  assert(change_display_name(email, DisplayNameUpdate { name: "Ada" }) == Err(NoSuchUser(email)))
}
