        ).fetchone():
            raise ApiError("Taken", email=body.email)
        conn.execute(
            "INSERT INTO users (email, first_name, last_name, password_hash, id) "
            "VALUES (?, ?, ?, ?, ?)",
            (
                body.email,
                first_name,
                last_name,
                hash_password(body.password),
