"""SQLite storage. The database file is $SHOP_DATABASE (default shop.db)."""

import os
import sqlite3
import threading
from collections.abc import Iterator
from contextlib import contextmanager

SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
    pos INTEGER PRIMARY KEY AUTOINCREMENT,
    sku TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    cents INTEGER NOT NULL,
    stock INTEGER NOT NULL,
    tags TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS users (
    pos INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL DEFAULT '',
    password_hash TEXT NOT NULL,
    id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS orders (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL,
    lines TEXT NOT NULL,
    total INTEGER NOT NULL,
    status TEXT NOT NULL
);
"""

_lock = threading.RLock()
_connection: sqlite3.Connection | None = None


def _migrate_user_names(conn: sqlite3.Connection) -> None:
    with conn:
        conn.execute("BEGIN IMMEDIATE")
        if not any(row["name"] == "name" for row in conn.execute("PRAGMA table_info(users)")):
            return
        conn.execute("ALTER TABLE users RENAME COLUMN name TO first_name")
        conn.execute("ALTER TABLE users ADD COLUMN last_name TEXT NOT NULL DEFAULT ''")
        rows = conn.execute("SELECT pos, first_name FROM users").fetchall()
        for row in rows:
            # Legacy names did not record where the first name ends.
            parts = row["first_name"].split(maxsplit=1)
            first_name = parts[0] if parts else ""
            last_name = parts[1].strip() if len(parts) == 2 else ""
            conn.execute(
                "UPDATE users SET first_name = ?, last_name = ? WHERE pos = ?",
                (first_name, last_name, row["pos"]),
            )


def _connect() -> sqlite3.Connection:
    global _connection
    if _connection is None:
        path = os.environ.get("SHOP_DATABASE", "shop.db")
        conn = sqlite3.connect(path, check_same_thread=False)
        try:
            conn.row_factory = sqlite3.Row
            conn.executescript(SCHEMA)
            _migrate_user_names(conn)
        except Exception:
            conn.close()
            raise
        _connection = conn
    return _connection


@contextmanager
def transaction() -> Iterator[sqlite3.Connection]:
    """A connection for one unit of work, committed at the end."""
    with _lock:
        conn = _connect()
        with conn:
            yield conn


def reset() -> None:
    """Close the database; the next request opens $SHOP_DATABASE again."""
    global _connection
    with _lock:
        if _connection is not None:
            _connection.close()
        _connection = None
