        order = Order(
            id=f"order-{next_id}",
            email=body.email,
            lines=body.lines,
            total=total,
            status=Open(),
        )
        conn.execute(
            "INSERT INTO orders (id, email, lines, total, status) VALUES (?, ?, ?, ?, ?)",
            (
                next_id,
                order.email,
                json.dumps([line.model_dump() for line in order.lines]),
