table users: User key email

type User {
  email: String,
  name: String,
  password_hash: String,
  id: String,
}

type Signup {
  email: String,
  name: String,
  password: String,
}

type DeleteAccount {
  password: String,
}

type Profile {
  email: String,
  name: String,
}

type UserError =
  | Taken(email: String)
  | BadLogin
  | NoSuchUser(email: String)

api fn signup(input: Signup) -> Result[Profile, UserError]
  route: POST "/users"
  effects: rand, store(users)
  requires: is_email(input.email) && str_len(trim(input.name)) > 0 && str_len(input.password) >= 8
{
  if is_some(get(users, input.email)) {
    return Err(Taken(input.email))
  }
  let user = User {
    email: input.email,
    name: trim(input.name),
    password_hash: hash_password(input.password),
    id: uuid(),
  }
  insert(users, user)
  return Ok(profile(user))
}

fn profile(u: User) -> Profile {
  return Profile { email: u.email, name: u.name }
}

api fn login(input: Signup) -> Result[Profile, UserError]
  route: POST "/login"
  effects: store(users)
{
  return match get(users, input.email) {
    Some(u) => match verify_password(input.password, u.password_hash) {
      true => Ok(profile(u)),
      false => Err(BadLogin),
    },
    None => Err(BadLogin),
  }
}

api fn delete_account(email: String, input: DeleteAccount) -> Result[Profile, UserError]
  route: POST "/users/{email}/delete"
  effects: store(users)
{
  let user = try match get(users, email) {
    Some(u) => Ok(u),
    None => Err(NoSuchUser(email)),
  }
  if !verify_password(input.password, user.password_hash) {
    return Err(BadLogin)
  }
  if delete(users, email) {
    return Ok(profile(user))
  }
  return Err(NoSuchUser(email))
}

test "account deletion requires the account password" {
  let email = "customer@example.com"
  let input = Signup { email: email, name: "Customer", password: "secret-password" }
  let credentials = DeleteAccount { password: input.password }
  let expected = Profile { email: email, name: input.name }
  assert(delete_account(email, credentials) == Err(NoSuchUser(email)))
  assert(signup(input) == Ok(expected))
  assert(delete_account(email, DeleteAccount { password: "wrong" }) == Err(BadLogin))
  assert(login(input) == Ok(expected))
  assert(delete_account(email, credentials) == Ok(expected))
  assert(login(input) == Err(BadLogin))
  assert(signup(input) == Ok(expected))
}
