  code: String,
}

api fn add_discount(input: Discount) -> Result[Discount, CatalogError]
  route: POST "/discounts"
  effects: store(discounts)
  requires: str_len(input.code) >= 3 && input.percent >= 1 && input.percent <= 100
{
  if is_some(get(discounts, input.code)) {
    return Err(Invalid("duplicate code " + input.code))
  }
  return Ok(save(discounts, input))
}

api fn apply_discount(id: Int, input: DiscountCode) -> Result[Order, CatalogError]
  route: POST "/orders/{id}/discount"
  effects: store(discounts), store(orders)
{
  let order = try discountable_order(id)
  return match get(discounts, input.code) {
    Some(d) => Ok(save(orders, discounted(order, d.percent))),
    None => Err(UnknownCode(input.code)),
  }
}

fn discountable_order(id: Int) -> Result[Order, CatalogError]
  effects: store(orders)
{
  let label = "order " + to_string(id)
  return match get(orders, id) {
    Some(o) => match o.status {
      Open => Ok(o),
      _ => Err(Invalid(label + " is not open")),
    },
    None => Err(Missing(label)),
  }
}

fn discounted(order: Order, percent: Int) -> Order {
  # Split off the remainder so the multiplication stays in the Int range.
  let tail = (order.total % 100) * percent
  let adjustment = match tail % 100 < 0 {
    true => 1,
    false => 0,
  }
  let reduction = (order.total / 100) * percent + tail / 100 - adjustment
  var updated = order
  updated.total = updated.total - reduction
  return updated
}

